/// Common generated framing boundary; implementation owns waiting and identity.
pub use abstraction_frame::FrameTransport;

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ServiceError {
    pub code: String,
    pub message: String,
}

#[derive(Debug)]
pub enum CallError<E> {
    /// Transport failure does not establish whether the receiver accepted work.
    Transport(E),
    Refusal(Refusal),
    Dispatch(&'static str),
    Service(ServiceError),
}

fn service_decode<T>(data: &[u8], decode: fn(&mut Reader) -> Result<T, Refusal>) -> Result<T, Refusal> {
    let mut r = Reader { buf: data, pos: 0, depth: 0 };
    r.skip_ws();
    let value = decode(&mut r)?;
    r.skip_ws();
    if r.pos != data.len() {
        return r.refuse("trailing_bytes");
    }
    Ok(value)
}

fn service_encode<T>(value: &T, check: fn(&T) -> Result<(), Refusal>, encode: fn(&mut Vec<u8>, &T, i32), decode: fn(&mut Reader) -> Result<T, Refusal>) -> Result<Vec<u8>, Refusal> {
    check(value)?;
    let mut data = Vec::new();
    encode(&mut data, value, 0);
    service_decode(&data, decode)?;
    Ok(data)
}

/// Register, rotate, revoke and inspect credentials by name in the receiving
/// account. Same-account identity alone grants nothing; each call is a rights
/// decision on the bound receiving subject. No call returns secret bytes, and
/// metadata derives nothing from them. An absent policy service reads
/// unavailable. An unconfigured platform store or a machine-scope runtime reads
/// no_secure_store; the provider substitutes no environment, file or
/// configuration source.
pub trait Holder {
    type Error;
    /// Conditionally register one secret for the receiving account. Gated by
    /// abstraction.credentials/holder.manage on resource account for the bound
    /// receiving subject; authorization precedes every store effect. The secret
    /// leaves the request only into the configured platform store. Returns
    /// stored, conflict, invalid, unsupported_kind, no_secure_store, exhausted,
    /// forbidden or unavailable.
    fn store(&self, expected_revision: String, registration: Registration) -> Result<StoreResult, Self::Error>;
    /// Conditionally replace the bytes of an existing record and its expiry;
    /// kind and scope are unchanged. Gated by holder.manage.
    fn rotate(&self, expected_revision: String, rotation: Rotation) -> Result<RotateResult, Self::Error>;
    /// Conditionally destroy the bytes and tombstone the record. Gated by
    /// holder.manage. A failed or uncertain reply claims no destruction;
    /// inspect List before another intent.
    fn revoke(&self, expected_revision: String, name: String) -> Result<RevokeResult, Self::Error>;
    /// Read the receiving account's records and the provider limits. Gated by
    /// abstraction.credentials/holder.read on resource account; every
    /// continuation rechecks. limit is 1..64.
    fn list(&self, cursor: String, limit: i64) -> Result<MetadataPage, Self::Error>;
    /// Read the receiving account's retained credential events. Gated by
    /// holder.read. Empty cursor starts at the oldest retained entry;
    /// max_entries is 1..256.
    fn audit(&self, cursor: String, max_entries: i64) -> Result<AuditPage, Self::Error>;
}

